local _, ns = ...

-- Progress (p) and hand-in (c) texts for quests whose other texts are in Data_Quests.lua
local extra = {
  [8115] = {c="Du klarede det! Du tog alle baserne! Godt gået, <Name>!\n\nDer var dem, der tvivlede på dine chancer, men jeg vidste, at du kunne det. Tak, og vid at Arator-ligaen har dig i høj agtelse, ligesom Skænderne fra De Forladte må frygte selve nævnelsen af dit navn!", p="Du har endnu ikke fuldført din mission, <Name>. Den er svær, men min tro på dig er stærk."},
  [8121] = {c="Godt arbejde, <Name>! Dine seneste handlinger i Arathi-bækkenet var ret besværlige, så deres succes er ganske prisværdig. Arator-ligaen må være i gang med at slikke sine sår efter de sidste sammenstød i bækkenet og, lad os håbe, genoverveje deres valg om at kæmpe her.", p="Vend tilbage til Arathi-bækkenet, <Name>, og udfør den opgave, du blev sendt for at udføre! Erobr og hold fire baser!"},
  [8122] = {c="Alliancens skrig, da du og dine kammerater angreb dem, kunne høres helt herfra, <Name>. Jeg kan næsten have medlidenhed med dem for smerten og frygten, du bragte ned over deres rækker. Næsten, men ikke helt.\n\nDin værdi for Skænderne er uden tvivl. Dine bedrifter i Arathi-bækkenet har været særdeles imponerende og har lydt gennem Varimatras' kamre... og selveste Den Mørke Dame."},
  [8741] = {c="Dine gerninger vil blive kendt af alle, mester. De vil synge dine lovprisninger fra Orgrimgrad til Sydhavets fjerneste egne. Alle vil kende til mesteren fra Den Bronze Flyvning, <Name>.", p="<Anakronos nikker.>"},
  [9120] = {c="I alle mine leveår havde jeg aldrig forventet at se dette...\n\n<Fader Montoy ser ud til at savle.>\n\nJo, du skal belønnes, kære dreng. Du skal belønnes rigeligt. Giv den her. Nu!", p="VELSIGNEDE LYS! Hvilken ondskab bærer du på, dreng?"},
  [9247] = {c="Blot ved at svare på kaldet står vi i din gæld, <Name>. Sølvdæmringen er sikker på, at de andre, som er her for at bistå os, gennem dit skinnende eksempel vil få stor indsigt i, hvordan vi bedst kaster Svøben-invasionen tilbage!", p="Ah, <Name>, det er godt at se dig."},
  [65602] = {c="<Gakin vender den træfigur rundt i hånden.>\n\nJeg fornemmer den følelsesmæssige energi, der bor i dette artefakt, uformindsket af tidens gang. Incubussen vil blive tiltrukket af den som en flue af honning.\n\nTykar skuffer aldrig.", p="Du er vendt tilbage. Vellykket, antager jeg?"},
  [65610] = {c="Hvad er det, du har dér, <Name>? Et halstørklæde lavet af... Månestof? Du må hellere ikke have planer om at fri til mig.", p="Ja, hvad er det?"},
  [78124] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [78127] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [78142] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [78143] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
