  [78149] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [78261] = {c="<Du lægger Xelthos-hornet i kisten>", p="<Kisten står tom.>"},
  [78676] = {c="<Du lægger Bhossca-øjet i kisten>", p="<Kisten står tom.>"},
  [78823] = {c="Nåh nu. Det her er da ret interessant..."},
  [78830] = {c="Nu er der en fjer til dit loft! Flot klaret, <Name>.\n\nDu kan hvile dig her et stykke tid, hvis du har lyst. Jeg er sikker på, at din rejse gennem ørkenen har været slidsom.", p="Hvordan går jagten? Fuglen har da ikke overmandet dig!"},
  [79007] = {c="Mens du snubler over resterne af endnu et forkullet lig, falder dit blik på en besked fastgjort til en træplanke."},
  [79008] = {c="Mens du snubler over resterne af endnu et forkullet lig, falder dit blik på en besked fastgjort til en træplanke."},
  [79091] = {c="Tak, <Name>. Siger du, at dette er fra Jernsmede-biblioteket? ...Jeg er sikker på, at de ikke vil savne det.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79092] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79093] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
