  [79095] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79096] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79097] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79192] = {c="Eventyrere og lejesoldater fra baglandet slår utvivlsomt lejr her. Hjørnet af en seddel, der flagrer i brisen, fanger dit øje, og du rækker ud efter den."},
  [79229] = {c="Ah, så du fandt endnu en..."},
  [79242] = {c="<Inde i skjulestedet finder du en lille kiste sammen med nogle mønter.>", p="<Med Illaris Nøgle låser du skjulestedet op.>"},
  [79358] = {c="<Hmpf... den store tyrefolk snuser, mens han læser pergamentet.>\n\nÉn ting er sikkert... hvem end denne seddel er fra, har ret i, at deres forberedelser går ubemærket hen. Vi har været for travlt optaget af at tackle kentaurerne og harpyerne til at sende vindryttere ud og patruljere kløften og klipperne.\n\nVi takker dig for at advare os om denne trussel, men vi har måske stadig brug for yderligere hjælp."},
  [79360] = {c="<Du rækker seddelen til Bath'rah, som læser den igennem og fniser en halvhjertet fnisen.>\n\nAh, så det er sandt, mon... Jeg har også fornemmet megen uro i elementarplanet, og dis må være en af årsagerne.\n\nAt oversvømme hele Tusindnåle ville kræve en kæmpe storm, og mange liv ville gå tabt.\n\nJeg tænker, jeg har lige den rette ting til dig, men den kommer ikke let."},
  [79361] = {c="Åh ja, ja. Nu er vi så småt påvej til at koge.", p="Ah, du bliver da en lille smule støvet derude?"},
  [79362] = {c="Lad os gøre os klar til en omgang bank, hva'?", p="Dine ben' ser lidt vaklende ud dér, ka'? Jorden ryst'r vel?"},
  [79363] = {c="Ryst dén slam af, vi er snart færdige, ik'?", p="Har du vadet ud i nogen fare endnu?"},
  [79535] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
  [79947] = {c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig.", p="Har du medbragt noget til at tilføje til vores samling?"},
