  [79974] = {c="Dværgisk Ingeniør, altid et vidunder."},
  [79975] = {c="Et lejrbål er lige blevet fodret med træ, men tegnene på en hurtig afgang er tydelige."},
  [79976] = {c="Tung seglduge er rullet over diverse udstyr. Du hjælper dig selv til flokken."},
  [79980] = {c="Du trækker en budbringertaske op af jorden. Proppet ned imellem forsyningerne ligger et beskidt pergament."},
